#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    sort(arr.begin(), arr.end());

    cout << "Sorted array: ";
    for (int x : arr) {
        cout << x << " ";
    }
    cout << endl;

    int sum = 0;
    for (int x : arr) {
        sum += x;
    }

    cout << "Sum: " << sum << endl;
    cout << "Minimum: " << arr.front() << endl;
    cout << "Maximum: " << arr.back() << endl;

    double average = (double)sum / n;
    cout << "Average: " << average << endl;

    return 0;
}
